// The HTTP API contract, shared by the Worker (implements it) and the browser (typed client).
// Reveal takes the Secret ID in the body, never the path, so IDs stay out of request URLs.
import { Schema } from "effect"
import { HttpApi, HttpApiEndpoint, HttpApiGroup } from "effect/http-api"
import { Base64UrlBytes, IV_BYTES, SALT_BYTES } from "./crypto.ts"
import { Expiry } from "./expiry.ts"

const Base64Url = Schema.String.check(Schema.isBase64Url())

/** Random bits in a Secret ID. */
export const SECRET_ID_BYTES = 16

/** 128 random bits, base64url without padding. Generated by the server. */
export const SecretId = Base64UrlBytes(SECRET_ID_BYTES).pipe(Schema.brand("SecretId"))
export type SecretId = typeof SecretId.Type

/** What the server keeps for a Secret (besides its Expiry), and what Reveal returns. */
export const StoredSecret = Schema.Struct({
  ciphertext: Base64Url,
  iv: Base64UrlBytes(IV_BYTES),
  /** PBKDF2 salt; present iff the Secret has a Passphrase. */
  salt: Schema.optionalKey(Base64UrlBytes(SALT_BYTES)),
  hasPassphrase: Schema.Boolean,
})
export type StoredSecret = typeof StoredSecret.Type

const CreateSecretBody = Schema.Struct({ ...StoredSecret.fields, expiry: Expiry })

/** One answer for not found, already revealed and expired alike, so none can be told apart. */
export class SecretGone extends Schema.TaggedError<SecretGone, { readonly brand: unique symbol }>()(
  "SecretGone",
  {},
  { httpApiStatus: 410 },
) {}

/** The Secret is over the size cap. The browser checks first; the server checks again. */
export class SecretTooLarge extends Schema.TaggedError<
  SecretTooLarge,
  { readonly brand: unique symbol }
>()("SecretTooLarge", {}, { httpApiStatus: 413 }) {}

/** The salt and the has-passphrase flag disagree: a salt comes with a Passphrase, and only then. */
export class MalformedSecret extends Schema.TaggedError<
  MalformedSecret,
  { readonly brand: unique symbol }
>()("MalformedSecret", {}, { httpApiStatus: 400 }) {}

/** Too many Secrets created from this IP lately; the sender should wait, not retry. */
export class RateLimited extends Schema.TaggedError<
  RateLimited,
  { readonly brand: unique symbol }
>()("RateLimited", {}, { httpApiStatus: 429 }) {}

const Secrets = HttpApiGroup.make("secrets")
  .add(
    HttpApiEndpoint.post("create", "/secrets", {
      payload: CreateSecretBody,
      success: Schema.Struct({ id: SecretId }),
      error: [SecretTooLarge, MalformedSecret, RateLimited],
    }),
    HttpApiEndpoint.post("reveal", "/secrets/reveal", {
      payload: Schema.Struct({ id: SecretId }),
      success: StoredSecret,
      error: SecretGone,
    }),
  )
  .prefix("/api")

const Health = HttpApiGroup.make("health")
  .add(
    HttpApiEndpoint.get("check", "/health", {
      success: Schema.Struct({ status: Schema.Literal("ok") }),
    }),
  )
  .prefix("/api")

export const Api = HttpApi.make("secret").add(Secrets).add(Health)
